def getMaxLuckyNumber(x, y, n):
    big = max(x, y)
    small = min(x, y)
    best_a = best_b = -1
    best_len = -1
    for b in range(n // small + 1):
        rem = n - b * small
        if rem >= 0 and rem % big == 0:
            a = rem // big
            length = a + b
            if length > best_len:
                best_len = length
                best_a = a; best_b = b
    if best_len < 0:
        return -1
    return int(str(big) * best_a + str(small) * best_b)

class Solution {
    public long getMaxLuckyNumber(int x, int y, int n) {
        int big = Math.max(x, y), small = Math.min(x, y);
        int bestA = -1, bestB = -1, bestLen = -1;
        for (int b = 0; b * small <= n; b++) {
            int rem = n - b * small;
            if (rem % big == 0) {
                int a = rem / big;
                int len = a + b;
                if (len > bestLen) { bestLen = len; bestA = a; bestB = b; }
            }
        }
        if (bestLen < 0) return -1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bestA; i++) sb.append(big);
        for (int i = 0; i < bestB; i++) sb.append(small);
        return Long.parseLong(sb.toString());
    }
}

